package com.labmaker.app;
import org.junit.*;import static org.junit.Assert.*;import org.junit.rules.TemporaryFolder;import okhttp3.*;import okhttp3.mockwebserver.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.util.*;import java.util.concurrent.TimeUnit;import java.util.zip.*;
public class ContributionUploadTest {
 @Rule public TemporaryFolder temp=new TemporaryFolder();final String id="12345678-1234-1234-1234-123456789abc",group="abcdefab-1234-1234-1234-123456789abc",exp="实验一";File cache;JSONArray rows;
 @Before public void setup()throws Exception {cache=temp.newFolder();rows=new JSONArray();}
 void add(String name,String ext,byte[] bytes)throws Exception {int index=rows.length();File file=new File(cache,"contribution-uploads/"+id+"/"+index+"."+ext);file.getParentFile().mkdirs();Files.write(file.toPath(),bytes);rows.put(new JSONObject().put("name",name).put("extension",ext).put("index",index).put("size",bytes.length).put("sha256",ContributionUpload.hash(bytes)));}
 List<ContributionUpload.Item> variant()throws Exception {add("自建变体_"+exp+".json","json","{\"实验原理\":[\"正文\"]}".getBytes(StandardCharsets.UTF_8));return ContributionUpload.plan(cache,id,exp,"variant",rows);}
 byte[] word()throws Exception {ByteArrayOutputStream out=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(out)){for(String name:new String[]{"[Content_Types].xml","word/document.xml"}){zip.putNextEntry(new ZipEntry(name));zip.write("<xml/>".getBytes());zip.closeEntry();}}return out.toByteArray();}
 List<ContributionUpload.Item> report()throws Exception {add("photo-1.jpg","jpg",new byte[]{(byte)255,(byte)216,(byte)255,0});add("report.docx","docx",word());add("manifest.json","json",new JSONObject().put("kind","report").put("exp",exp).put("score","8.5").put("note","").toString().getBytes(StandardCharsets.UTF_8));return ContributionUpload.plan(cache,id,exp,"report",rows);}
 ContributionUpload upload(MockWebServer s){OkHttpClient client=new OkHttpClient.Builder().followRedirects(false).followSslRedirects(false).retryOnConnectionFailure(false).callTimeout(2,TimeUnit.SECONDS).build();return new ContributionUpload(new FeedbackUpload(client,s.url("/credentials"),s.url("/")));}
 JSONObject credentials(MockWebServer s,String kind,List<ContributionUpload.Item> files)throws Exception {JSONArray items=new JSONArray();for(ContributionUpload.Item f:files){String root="contributions/"+(kind.equals("variant")?"variants":"reports")+"/"+exp+"/",object=root+group+"/"+f.name;items.put(new JSONObject().put("key",root+id+"/"+f.name).put("objectKey",object).put("size",f.size).put("putUrl",s.url("/").newBuilder().addPathSegments(object).addQueryParameter("signed","test").build().toString()));}return new JSONObject().put("ok",true).put("items",items);}
 @Test public void fixedPathsHashesAndVariantShapeAreRequired()throws Exception {List<ContributionUpload.Item> files=variant();assertEquals(1,files.size());rows.getJSONObject(0).put("index",1);try{ContributionUpload.plan(cache,id,exp,"variant",rows);fail();}catch(IOException expected){}rows.getJSONObject(0).put("index",0).put("sha256","0".repeat(64));try{ContributionUpload.plan(cache,id,exp,"variant",rows);fail();}catch(IOException expected){}for(String bad:new String[]{"../bad", ""})try{ContributionUpload.plan(cache,bad,exp,"variant",rows);fail();}catch(IOException expected){}}
 @Test public void reportsRequireValidWordAndFinalGradedManifest()throws Exception {assertEquals(3,report().size());ContributionUpload.word(word());try{ContributionUpload.word(new byte[]{80,75,3,4});fail();}catch(Exception expected){}File manifest=new File(cache,"contribution-uploads/"+id+"/2.json");byte[] invalid=new JSONObject().put("kind","report").put("exp",exp).put("score","6.5").toString().getBytes(StandardCharsets.UTF_8);Files.write(manifest.toPath(),invalid);rows.getJSONObject(2).put("size",invalid.length).put("sha256",ContributionUpload.hash(invalid));try{ContributionUpload.plan(cache,id,exp,"report",rows);fail();}catch(IOException expected){}}
 @Test public void bindsEveryTicketAndRejectsForeignOrDuplicateObjects()throws Exception {try(MockWebServer s=new MockWebServer()){s.start();List<ContributionUpload.Item> files=report();ContributionUpload u=upload(s);String prefix="contributions/reports/"+exp+"/"+id+"/";assertEquals(3,u.tickets(credentials(s,"report",files),files,prefix).size());for(String field:new String[]{"putUrl","objectKey","size","key"}){JSONObject raw=credentials(s,"report",files),item=raw.getJSONArray("items").getJSONObject(0);item.put(field,field.equals("size")?1:"bad");try{u.tickets(raw,files,prefix);fail(field);}catch(IOException expected){}}JSONObject raw=credentials(s,"report",files);raw.getJSONArray("items").put(1,raw.getJSONArray("items").getJSONObject(0));try{u.tickets(raw,files,prefix);fail();}catch(IOException expected){}}}
 @Test public void putsFilesOnceInOrderAndManifestLast()throws Exception {try(MockWebServer s=new MockWebServer()){s.start();List<ContributionUpload.Item> files=report();s.enqueue(new MockResponse().setBody(credentials(s,"report",files).toString()));for(int i=0;i<3;i++)s.enqueue(new MockResponse().setResponseCode(200));JSONObject result=upload(s).submit(id,exp,"report",files,new FeedbackUpload.Work());assertEquals("sent",result.getString("state"));assertEquals(3,result.getInt("sent"));s.takeRequest();for(ContributionUpload.Item file:files){RecordedRequest request=s.takeRequest();assertEquals("PUT",request.getMethod());assertEquals("true",request.getHeader("x-cos-forbid-overwrite"));assertNull(request.getHeader("Cookie"));assertNull(request.getHeader("Authorization"));assertArrayEquals(ContributionUpload.read(file),request.getBody().readByteArray());}assertEquals(4,s.getRequestCount());}}
 @Test public void droppedSecondPutStopsBatchWithoutRetryOrManifest()throws Exception {try(MockWebServer s=new MockWebServer()){s.start();List<ContributionUpload.Item> files=report();s.enqueue(new MockResponse().setBody(credentials(s,"report",files).toString()));s.enqueue(new MockResponse().setResponseCode(200));s.enqueue(new MockResponse().setSocketPolicy(SocketPolicy.DISCONNECT_AFTER_REQUEST));JSONObject result=upload(s).submit(id,exp,"report",files,new FeedbackUpload.Work());assertEquals("unknown",result.getString("state"));assertEquals(1,result.getInt("sent"));assertEquals(3,s.getRequestCount());}}
 @Test public void badCredentialsAndCancelledWorkDoNotPut()throws Exception {try(MockWebServer s=new MockWebServer()){s.start();List<ContributionUpload.Item> files=variant();s.enqueue(new MockResponse().setBody("{}"));try{upload(s).submit(id,exp,"variant",files,new FeedbackUpload.Work());fail();}catch(IOException expected){}assertEquals(1,s.getRequestCount());FeedbackUpload.Work work=new FeedbackUpload.Work();work.cancel();assertEquals("cancelled",upload(s).submit(id,exp,"variant",files,work).getString("state"));assertEquals(1,s.getRequestCount());}}
 @Test public void changedSourceNeverUploadsDifferentBytes()throws Exception {try(MockWebServer s=new MockWebServer()){s.start();List<ContributionUpload.Item> files=variant();Files.write(files.get(0).file.toPath(),new byte[]{1,2,3});s.enqueue(new MockResponse().setBody(credentials(s,"variant",files).toString()));try{upload(s).submit(id,exp,"variant",files,new FeedbackUpload.Work());fail();}catch(IOException expected){}assertEquals(1,s.getRequestCount());}}
}
